(()=>{const o=document.querySelector(".nav-toggle"),r=document.getElementById("nav-links");o.addEventListener("click",()=>{const e=r.classList.toggle("open");o.setAttribute("aria-expanded",String(e))}),r.addEventListener("click",e=>{e.target.closest("a")&&(r.classList.remove("open"),o.setAttribute("aria-expanded","false"))});const a=document.querySelectorAll(".reveal");if("IntersectionObserver"in window){const e=new IntersectionObserver(t=>{t.forEach(n=>{n.isIntersecting&&(n.target.classList.add("in"),e.unobserve(n.target))})},{threshold:.15});a.forEach(t=>e.observe(t))}else a.forEach(e=>e.classList.add("in"));const i=window.matchMedia("(prefers-reduced-motion: reduce)").matches;document.querySelectorAll("[data-count]").forEach(e=>{const t=Number(e.dataset.count);if(i){e.textContent=t.toLocaleString();return}const n=performance.now(),d=1400,s=l=>{const c=Math.min((l-n)/d,1);e.textContent=Math.round(t*(1-Math.pow(1-c,3))).toLocaleString(),c<1&&requestAnimationFrame(s)};requestAnimationFrame(s)}),document.getElementById("year").textContent=new Date().getFullYear()})();
